create or replace function app.fact_client_insured_count(p_client uuid) returns integer
  language plpgsql stable security definer set search_path = ''
as $$
begin
  if not app.active() or not coalesce((exists (select 1 from public.clients v where v.id = p_client and ((select app.active()) and ( ((select app.is_staff()) and (select app.can_any(array['clients.read', 'leads.manage', 'deals.manage', 'contracts.read', 'invoices.read', 'policies.read', 'kp.read', 'policy_changes.read']::text[]))) or ((select app.role()) = 'hr' and (id = (select app.company_id()))) )))), false) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return (select count(*)::int from public.insured i where i.client_id = p_client and i.status = 'active');
end $$;
comment on function app.fact_client_insured_count(uuid) is 'Active insured persons of a client the caller sees (the client card counter).';
revoke execute on function app.fact_client_insured_count(uuid) from public;
grant execute on function app.fact_client_insured_count(uuid) to authenticated, service_role;

create or replace function app.fact_client_legal_form(p_client uuid) returns text
  language plpgsql stable security definer set search_path = ''
as $$
begin
  if not app.active() or not coalesce((app.is_staff() or p_client = app.company_id()), false) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return (select c.legal_form from public.clients c where c.id = p_client);
end $$;
comment on function app.fact_client_legal_form(uuid) is 'Legal form shown next to a client name (MIG staff; HR — the own company).';
revoke execute on function app.fact_client_legal_form(uuid) from public;
grant execute on function app.fact_client_legal_form(uuid) to authenticated, service_role;

create or replace function app.fact_client_claim_figures(p_client uuid) returns jsonb
  language plpgsql stable security definer set search_path = ''
as $$
begin
  if not app.active() or not coalesce(((select app.can('clients.read')) and exists (select 1 from public.clients v where v.id = p_client and ((select app.active()) and ( ((select app.is_staff()) and (select app.can_any(array['clients.read', 'leads.manage', 'deals.manage', 'contracts.read', 'invoices.read', 'policies.read', 'kp.read', 'policy_changes.read']::text[]))) or ((select app.role()) = 'hr' and (id = (select app.company_id()))) )))), false) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return (select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'category', c.category, 'serviceDate', c.service_date::text, 'createdAt', to_char(c.created_at at time zone app.tz(), 'YYYY-MM-DD"T"HH24:MI:SS"+05:00"'),
      'status', c.status, 'amountClaimed', c.amount_claimed, 'amountApproved', c.amount_approved)) order by c._pos), '[]'::jsonb)
    from public.claims c where c.client_id = p_client);
end $$;
comment on function app.fact_client_claim_figures(uuid) is 'Anonymous figures (category, dates, status, amounts) of the claims of a client, for clients.read: loss statistics.';
revoke execute on function app.fact_client_claim_figures(uuid) from public;
grant execute on function app.fact_client_claim_figures(uuid) to authenticated, service_role;

